// Rasterize design/icon.svg into public/icons/*.png. Chrome MV3 rejects SVG in
// manifest `icons` / `action.default_icon`, so the SVG is the source of truth and
// the PNGs are build artifacts (gitignored, regenerated by dev/build).
// The source lives in design/, not assets/ — crxjs globs root assets/ into the
// bundle (web_accessible_resources), which would ship the SVG for no reason.
//
// Three variants per size, swapped per tab by background/badge.ts:
//   icon-<n>.png      base brand mark (manifest default; tabs with no verdict)
//   icon-ok-<n>.png   + green check corner  — downloadable animepahe anime page
//   icon-bad-<n>.png  + red cross corner    — on animepahe, wrong page
// The corner disc is composed onto the one base SVG rather than kept as separate
// files, so the glyph itself has a single source of truth.
import { mkdir, readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const src = resolve(root, 'design/icon.svg');
const dest = resolve(root, 'public/icons');
const SIZES = [16, 32, 48, 128];

// Corner disc, in the base viewBox (0 0 128 128). The dark ring separates it from
// the orange glyph underneath. At 16px the tick/cross is sub-pixel mush — the disc
// COLOUR is what carries the verdict there, the glyph sharpens from 32px up.
const disc = (fill, glyph) => `
  <circle cx="94" cy="94" r="34" fill="#14151a"/>
  <circle cx="94" cy="94" r="27" fill="${fill}"/>
  ${glyph}
`;
const OVERLAYS = {
  '': '',
  '-ok': disc(
    '#2ea043',
    '<path d="M81 94l10 10 18-19" fill="none" stroke="#fff" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/>',
  ),
  '-bad': disc(
    '#d1242f',
    '<path d="M84 84l20 20M104 84l-20 20" fill="none" stroke="#fff" stroke-width="9" stroke-linecap="round"/>',
  ),
};

const base = await readFile(src, 'utf8');
await mkdir(dest, { recursive: true });

for (const [suffix, overlay] of Object.entries(OVERLAYS)) {
  const svg = Buffer.from(overlay ? base.replace(/<\/svg>\s*$/, `${overlay}</svg>`) : base);
  for (const size of SIZES) {
    const name = `icon${suffix}-${size}.png`;
    // density: render the vector at 3x before downsampling — librsvg rasterizes at
    // the SVG's intrinsic 128px otherwise, and 128 -> 16 loses the thin strokes.
    await sharp(svg, { density: 384 }).resize(size, size).png().toFile(resolve(dest, name));
    console.log(`generated ${name}`);
  }
}
